func TestSubmissionAuthMechanismsAdvertised(t *testing.T) {
	sess := newTestSubmissionSession(&submissionAuthCaller{})
	mechs := sess.AuthMechanisms()
	want := map[string]bool{sasl.Plain: true, sasl.OAuthBearer: true}
	for _, m := range mechs {
		if !want[m] {
			t.Errorf("advertised unexpected mech %q", m)
		}
		delete(want, m)
	}
	for m := range want {
		t.Errorf("missing required mech %q", m)
	}
}

func TestSubmissionPLAINFailsOnAuthzIDMismatch(t *testing.T) {
	// RFC 4616: authzid must be empty or equal to authcid.
	// Mismatch returns errSubmissionAuthFailed pre-resolution, so
	// no validate_recipient call should fire.
	caller := &submissionAuthCaller{}
	sess := newTestSubmissionSession(caller)
	payload := auth.BuildPlainPayload("eve@evil", "alice@example.com", "any")
	err := sess.authenticate(sasl.Plain, payload)
	if err == nil {
		t.Fatal("authzid mismatch must produce an AUTH error")
	}
	if len(caller.callsOf(wsrpc.MethodValidateRecipient)) != 0 {
		t.Fatal("authzid mismatch must NOT call validate_recipient")
	}
	if got := caller.callsOf(wsrpc.MethodReportAuthEvent); len(got) != 1 {
		t.Fatalf("report_auth_event fired %d times on authzid-mismatch, want 1", len(got))
	}
}

// ── Phase D.7: per-(credential, IP) lockout integration ─────────

// TestSubmissionAuthLockoutRejectsAfter30Failures pins the wire
// contract: with a 30-failure-per-minute limit, 30 failed AUTH
// attempts from the same (presented_user, credential, source_ip)
// produce one fetch_wrapped_submission_token + AEAD-unwrap each (the
// gate is the normal post-AEAD failure path) and the 31st attempt
// returns SMTP 421 4.7.0 *before* any nest call fires — no
// fetch_wrapped_submission_token on the 31st, no AEAD attempt, and
// no report_auth_event row.
func TestSubmissionAuthLockoutRejectsAfter30Failures(t *testing.T) {
	t.Parallel()
	blob := mustReadFixture(t, "wrapped_submission_token.bin")
	caller := &submissionAuthCaller{
		validateRecipientReplyHex: hex.EncodeToString(fixtureActorID()),
		submissionBlob:            blob,
	}
	sess := newTestSubmissionSession(caller)
	lc := *sess.backend.cfg.current()
	lc.authLockout = NewAuthLockout(30, time.Minute, newFakeLockoutClock())
	sess.backend.cfg = staticMTAConfig(&lc)

	// 30 failed PLAIN AUTH attempts. Each goes through the full
	// path (validate_recipient → fetch_wrapped_submission_token →
	// unseal-fail → report_auth_event{fail}) and records a failure
	// against the lockout bucket.
	for i := 0; i < 30; i++ {
		err := sess.authenticate(sasl.Plain,
			auth.BuildPlainPayload("", "alice@example.com", "WRONG-PASSWORD"))
		if err == nil {
			t.Fatalf("attempt %d: expected wrong-password failure, got nil", i+1)
		}
		if err != errSubmissionAuthFailed {
			t.Fatalf("attempt %d: wire = %v, want errSubmissionAuthFailed", i+1, err)
		}
	}

	priorFetchCount := len(caller.callsOf(wsrpc.MethodFetchWrappedSubmissionToken))
	priorAuthEventCount := len(caller.callsOf(wsrpc.MethodReportAuthEvent))
	if priorFetchCount != 30 {
		t.Fatalf("setup invariant: fetch_wrapped_submission_token fired %d times; want 30", priorFetchCount)
	}
	if priorAuthEventCount != 30 {
		t.Fatalf("setup invariant: report_auth_event fired %d times; want 30", priorAuthEventCount)
	}

	// 31st attempt MUST trip the lockout: 421 4.7.0 on the wire, no
	// new fetch_wrapped_submission_token call, no new
	// report_auth_event audit row.
	err := sess.authenticate(sasl.Plain,
		auth.BuildPlainPayload("", "alice@example.com", "WRONG-PASSWORD"))
	if err != errSubmissionAuthLockedOut {
		t.Fatalf("31st attempt: wire = %v, want errSubmissionAuthLockedOut", err)
	}

	if got := len(caller.callsOf(wsrpc.MethodFetchWrappedSubmissionToken)); got != priorFetchCount {
		t.Errorf("31st attempt fired fetch_wrapped_submission_token (got %d total, want %d)",
			got, priorFetchCount)
	}
	if got := len(caller.callsOf(wsrpc.MethodReportAuthEvent)); got != priorAuthEventCount {
		t.Errorf("31st attempt fired report_auth_event (got %d total, want %d)",
			got, priorAuthEventCount)
	}

	// 32nd attempt with the *correct* password also locks out — the
	// budget is per (user, IP) and a brute-forcer can't slip through
	// on a guess once the gate closes. Reset only fires on a real
	// AUTH success, which can't happen while the gate is locked.
	err = sess.authenticate(sasl.Plain,
		auth.BuildPlainPayload("", "alice@example.com", string(fixturePlainPassword)))
	if err != errSubmissionAuthLockedOut {
		t.Fatalf("32nd attempt (correct password): wire = %v, want errSubmissionAuthLockedOut", err)
	}
	if got := len(caller.callsOf(wsrpc.MethodFetchWrappedSubmissionToken)); got != priorFetchCount {
		t.Errorf("locked-out correct-password attempt still fired fetch_wrapped_submission_token (got %d total, want %d)",
			got, priorFetchCount)
	}
}

// TestSubmissionAuthLockoutResetsOnSuccess — a legitimate AUTH (the
// fixture password) before the 31st attempt resets the bucket, so the
// next 30 fresh failures don't trip the gate. Mirrors the typo-fest
// shape: an honest user fat-fingers a few times, then succeeds, and
// shouldn't be locked out by their prior typos.
func TestSubmissionAuthLockoutResetsOnSuccess(t *testing.T) {
	t.Parallel()
	blob := mustReadFixture(t, "wrapped_submission_token.bin")
	caller := &submissionAuthCaller{
		validateRecipientReplyHex: hex.EncodeToString(fixtureActorID()),
		submissionBlob:            blob,
	}
	sess := newTestSubmissionSession(caller)
	lc := *sess.backend.cfg.current()
	lc.authLockout = NewAuthLockout(3, time.Minute, newFakeLockoutClock())
	sess.backend.cfg = staticMTAConfig(&lc)

	// Two typos.
	for i := 0; i < 2; i++ {
		if err := sess.authenticate(sasl.Plain,
			auth.BuildPlainPayload("", "alice@example.com", "WRONG")); err == nil {
			t.Fatalf("typo %d should fail", i+1)
		}
	}
	// Success — the lockout bucket resets.
	if err := sess.authenticate(sasl.Plain,
		auth.BuildPlainPayload("", "alice@example.com", string(fixturePlainPassword))); err != nil {
		t.Fatalf("correct password must succeed: %v", err)
	}
	// Reset the session so we can probe AUTH again with the lockout
	// bucket cleared. (The successful AUTH stashed state on the
	// session; we want to drive the wire path fresh.)
	sess.mu.Lock()
	sess.authenticated = false
	sess.submissionToken = nil
	sess.actorID = nil
	sess.credentialID = ""
	sess.authedLocalPart = ""
	sess.mu.Unlock()

	// Three fresh failures must NOT lock — the bucket was reset by
	// the successful AUTH above. The 3rd failure brings count back
	// to 3 but doesn't lock the *4th* attempt either, because limit=3
	// means 3 failures still allowed.
	for i := 0; i < 3; i++ {
		if err := sess.authenticate(sasl.Plain,
			auth.BuildPlainPayload("", "alice@example.com", "WRONG")); err != errSubmissionAuthFailed {
			t.Fatalf("fresh failure %d after reset: wire = %v, want errSubmissionAuthFailed", i+1, err)
		}
	}
}

// ── Helpers ───────────────────────────────────────────────────────

func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// Compile-time assertion: submissionAuthCaller satisfies wsrpc.Caller's
// call shape. Kept local to avoid pulling wsrpc into the test
// imports beyond the package boundary.
type wsrpcCaller interface {
	Call(ctx context.Context, method string, body, reply any) error
}

var _ wsrpcCaller = (*submissionAuthCaller)(nil)
